-- ===== PathfindingEngine.lua =====
-- PATHFINDING & UNSTUCK ENGINE

local function shouldContinue(token)
    return pathfindingEnabled and routineToken == token
end

local function attemptUnstuck(humanoid, rootPart)
    setStatus("Unsticking character...", Color3.fromRGB(240, 200, 120))

    humanoid.Jump = true
    local moveBackVector = -rootPart.CFrame.LookVector * 6 + Vector3.new(math.random(-4, 4), 0, math.random(-4, 4))
    humanoid:MoveTo(rootPart.Position + moveBackVector)

    task.wait(0.8)
end

local function walkToPosition(targetPosition, token)
    local character = player.Character
    if not character then return false end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local rootPart = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or not rootPart then return false end

    while shouldContinue(token) do
        if consecutivePathFailures >= MAX_CONSECUTIVE_FAILURES then
            clickGiveUpButton()
            return false
        end

        local effectiveTarget = targetPosition
        if consecutivePathFailures >= 3 then
            local detourOffset = Vector3.new(
                math.random(-12, 12),
                0,
                math.random(-12, 12)
            )
            effectiveTarget = targetPosition + detourOffset
        elseif consecutivePathFailures > 0 then
            local lightOffset = Vector3.new(
                math.random(-4, 4),
                0,
                math.random(-4, 4)
            )
            effectiveTarget = targetPosition + lightOffset
        end

        local path = PathfindingService:CreatePath(PATH_OPTIONS)
        local computed = pcall(function()
            path:ComputeAsync(rootPart.Position, effectiveTarget)
        end)

        if not computed or path.Status ~= Enum.PathStatus.Success then
            consecutivePathFailures += 1
            setStatus("Path failed (" .. consecutivePathFailures .. "/" .. MAX_CONSECUTIVE_FAILURES .. ")", Color3.fromRGB(240, 140, 150))

            if consecutivePathFailures >= MAX_CONSECUTIVE_FAILURES then
                clickGiveUpButton()
                return false
            end

            attemptUnstuck(humanoid, rootPart)
        else
            drawPath(path)
            setStatus("Walking...", Color3.fromRGB(180, 220, 255))

            local waypoints = path:GetWaypoints()

            local autoJumpConn = nil
            if autoJumpEnabled then
                autoJumpConn = RunService.PreRender:Connect(function()
                    if humanoid and humanoid.Health > 0 then
                        humanoid.Jump = true
                    end
                end)
            end

            local stepFailed = false
            for _, waypoint in ipairs(waypoints) do
                if not shouldContinue(token) or humanoid.Health <= 0 then
                    if autoJumpConn then autoJumpConn:Disconnect() end
                    return false
                end

                if waypoint.Action == Enum.PathWaypointAction.Jump and not autoJumpEnabled then
                    humanoid.Jump = true
                end

                humanoid:MoveTo(waypoint.Position)

                local reached = false
                local finished = false

                local moveConnection = humanoid.MoveToFinished:Connect(function(result)
                    reached = result
                    finished = true
                end)

                local startedAt = os.clock()

                while not finished and shouldContinue(token) do
                    if os.clock() - startedAt >= 6 then
                        break
                    end
                    RunService.Heartbeat:Wait()
                end

                if moveConnection then moveConnection:Disconnect() end

                if not reached then
                    if autoJumpConn then autoJumpConn:Disconnect() end
                    consecutivePathFailures += 1
                    setStatus("Stuck (" .. consecutivePathFailures .. "/" .. MAX_CONSECUTIVE_FAILURES .. ")", Color3.fromRGB(240, 140, 150))

                    attemptUnstuck(humanoid, rootPart)
                    stepFailed = true
                    break
                end
            end

            if autoJumpConn then autoJumpConn:Disconnect() end

            if not stepFailed then
                consecutivePathFailures = 0
                setStatus("Reached target", Color3.fromRGB(200, 230, 255))
                return true
            end
        end
    end

    return false
end

-- ===== AutomationSequences.lua =====
-- AUTOMATION SEQUENCES

local plr = game.Players.LocalPlayer

local function resetPlr()
    if plr.Character then
        plr.Character:BreakJoints()
    end
end

local function getLimeTarget()
    local mapFolder = Workspace:WaitForChild("Map", 5)
    if not mapFolder then return nil, nil, nil end

    local limeModel = mapFolder:WaitForChild("Lime", 5)
    if not limeModel then return nil, nil, nil end

    local torso = limeModel:WaitForChild("Torso", 5)
    if not torso then return nil, nil, nil end

    return limeModel, torso.Position, torso:FindFirstChildWhichIsA("ProximityPrompt")
end

local function startWatermelonMinigameSequence(token)
    setStatus("Searching Watermelon...", Color3.fromRGB(240, 220, 160))
    local targetPrompt, watermelonPart = findWatermelonPrompt()
    local startTime = os.clock()

    while not targetPrompt and shouldContinue(token) do
        -- WATERMELON SEARCH TIMEOUT: If looking for more than 3 minutes (180s), give up
        if os.clock() - startTime > 180 then
            setStatus("Search timeout! Giving up...", Color3.fromRGB(255, 100, 100))
            clickGiveUpButton()
            return
        end

        task.wait(0.5)
        targetPrompt, watermelonPart = findWatermelonPrompt()
    end

    if not targetPrompt or not shouldContinue(token) then
        setStatus("Watermelon missing", Color3.fromRGB(240, 140, 150))
        task.wait(2)
        return
    end

    if watermelonPart and watermelonPart:IsA("BasePart") then
        walkToPosition(watermelonPart.Position, token)
    end

    if not shouldContinue(token) then return end

    task.wait(0.3)
    local freshPrompt, freshPart = findWatermelonPrompt()
    freshPrompt = freshPrompt or targetPrompt
    freshPart = freshPart or watermelonPart

    if freshPrompt and freshPart then
        if not isWithinPromptRange(freshPrompt, freshPart) then
            walkToPosition(freshPart.Position, token)
            task.wait(0.3)

            local recheckPrompt, recheckPart = findWatermelonPrompt()
            freshPrompt = recheckPrompt or freshPrompt
            freshPart = recheckPart or freshPart
        end

        if isWithinPromptRange(freshPrompt, freshPart) and shouldContinue(token) then
            spamPromptUntilRemoved(freshPrompt, freshPart, token)
        end
    end

    updateAttemptsUI()

    task.wait(1)
end

local function executeRoutine(token)
    if not shouldContinue(token) then return end

    local _, limePos, limePrompt = getLimeTarget()
    if not limePos or not limePrompt then
        setStatus("Waiting for Lime...", Color3.fromRGB(160, 168, 185))
        task.wait(1)
        return
    end

    if walkToPosition(limePos, token) then
        if not shouldContinue(token) then return end

        setStatus("Interacting with Lime...", Color3.fromRGB(240, 220, 160))
        triggerPromptEnhanced(limePrompt)

        task.wait(2)
        if not shouldContinue(token) then return end

        -- LIME CONVERSATION STUCK CHECK
        local conversationStartTime = os.clock()

        local minigameBtn = waitForChoiceButton("[ Minigame ]", 8, token)
        
        if not minigameBtn then
            if os.clock() - conversationStartTime > 60 then
                setStatus("Stuck on Lime! Resetting...", Color3.fromRGB(255, 100, 100))
                resetPlr()
                task.wait(5)
                return
            end
        end

        if minigameBtn then
            task.wait(0.5)
            clickChoiceButton(minigameBtn)

            local ticketBtn = waitForChoiceButton("[ -1 Minigame Ticket ]", 8, token)
            
            if not ticketBtn then
                if os.clock() - conversationStartTime > 60 then
                    setStatus("Stuck on Ticket! Resetting...", Color3.fromRGB(255, 100, 100))
                    resetPlr()
                    task.wait(5)
                    return
                end
            end

            if ticketBtn then
                task.wait(0.5)
                clickChoiceButton(ticketBtn)

                task.wait(1)
                if shouldContinue(token) then
                    startWatermelonMinigameSequence(token)
                end
            end
        end
    end
end


-- ===== ControllerExecution.lua =====
-- CONTROLLER EXECUTION & TOGGLES

local function stopRoutine()
    routineToken += 1
    clearPathVisuals()
    setStatus("Idle", Color3.fromRGB(160, 168, 185))
end

local function startRoutineLoop()
    routineToken += 1
    local currentToken = routineToken

    task.spawn(function()
        while pathfindingEnabled and routineToken == currentToken do
            executeRoutine(currentToken)
            task.wait(0.5)
        end
    end)
end

togglePathButton.MouseButton1Click:Connect(function()
    pathfindingEnabled = not pathfindingEnabled
    updatePathToggle()

    if pathfindingEnabled then
