            local menuSize = contextMenu.AbsoluteSize

            if mousePos.X < menuPos.X or mousePos.X > menuPos.X + menuSize.X
                or mousePos.Y < menuPos.Y or mousePos.Y > menuPos.Y + menuSize.Y then

                contextMenu.Visible = false
            end
        end
    end
end)
